                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(cells)>=6:
                glyphs.append((col,cells))
    for col,cells in glyphs:
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        for r,c in cells: out[r][c]=0
